@push('scripts')<script>$(function(){var $t=$('#schedules-table'),text=$.fn.dataTable.render.text(),states={OVERDUE:['เกินกำหนด','app-status-danger'],DUE_SOON:['ใกล้ครบกำหนด','app-badge-warning'],UPCOMING:['ตามแผน','app-badge-success']},table=$t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:$t.data('url'),data:function(d){d.active=$('#schedule-active').val();}},order:[[2,'asc']],buttons:[window.erpExcelButton($t)],columns:[{data:'asset_label',orderable:false,render:text.display},{data:'title',name:'title',render:text.display},{data:'next_due_date_label',name:'next_due_date',render:text.display},{data:'responsible_label',orderable:false,render:text.display},{data:'due_state',orderable:false,render:function(v,t){return t==='display'?'<span class="badge '+states[v][1]+'">'+states[v][0]+'</span>':v;}},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,t,row){return t==='display'?(row.complete_url?'<button class="btn btn-sm btn-outline-success js-schedule-complete" data-url="'+text.display(row.complete_url)+'">ทำแล้ว</button> ':'')+'<a class="btn btn-sm btn-outline-dark" href="'+text.display(row.edit_url)+'">แก้ไข</a>':'';}}]}));$('#schedule-active').on('change',function(){table.ajax.reload();});$t.on('click','.js-schedule-complete',function(){var $b=$(this);Swal.fire({icon:'question',title:'บันทึกว่าดำเนินการแล้ว?',input:'date',inputValue:@json(today()->toDateString()),showCancelButton:true,preConfirm:function(v){if(!v)Swal.showValidationMessage('กรุณาเลือกวันที่');}}).then(function(r){if(!r.isConfirmed)return;$b.prop('disabled',true);$.post($b.data('url'),{_token:@json(csrf_token()),completed_date:r.value}).done(function(res){Swal.fire({icon:'success',title:res.msg});table.ajax.reload(null,false);}).fail(window.erpAjaxError).always(function(){$b.prop('disabled',false);});});});});</script>@endpush
